def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    objects = []

    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)

        # A candidate is a rectangular frame with a complete perimeter.
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = ([(r0, c) for c in range(c0, c1 + 1)] +
                     [(r1, c) for c in range(c0, c1 + 1)] +
                     [(r, c0) for r in range(r0 + 1, r1)] +
                     [(r, c1) for r in range(r0 + 1, r1)])
        if not all(grid[r][c] == color for r, c in perimeter):
            continue

        ih, iw = r1 - r0 - 1, c1 - c0 - 1
        pattern = [[grid[r0 + 1 + i][c0 + 1 + j] == color
                    for j in range(iw)] for i in range(ih)]
        objects.append((color, r0, r1, c0, c1, ih, iw, pattern))

    sources = [(ih, iw, pattern) for _, _, _, _, _, ih, iw, pattern in objects
               if any(any(row) for row in pattern)]

    out = [row[:] for row in grid]
    for color, r0, r1, c0, c1, ih, iw, pattern in objects:
        if any(any(row) for row in pattern):
            continue
        matching = next((p for sh, sw, p in sources if (sh, sw) == (ih, iw)), None)
        if matching is None:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if grid[r][c] == color:
                        out[r][c] = 0
        else:
            for i in range(ih):
                for j in range(iw):
                    out[r0 + 1 + i][c0 + 1 + j] = color if matching[i][j] else 0

    return out
